const email = $input.item.json;

function stripHtml(html) { 
  return html.replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function stripHistory(text) { 
  return text.split(/(?:Le |On |From:)/)[0].trim();
}

function stripSignature(text) { 
  return text.split(/(?:Cordialement|Bien cordialement|Cdlt)/i)[0].trim();
}

function cleanup(text) { 
  return text.replace(/\s+/g, ' ').trim();
}

let raw = email.text || email.html || "";
if (email.html && !email.text) { 
  raw = stripHtml(email.html); 
}

let cleaned = stripHistory(raw);
cleaned = stripSignature(cleaned);
cleaned = cleanup(cleaned);

return {
  json: {
    id: email.messageId || email.id || "",
    subject: email.subject || "",
    threadId: email.threadId || "",
    internalDate: email.internalDate || "",
    cleanText: cleaned
  }
};

